  8	/**
  9	 * Lane-close agent session capture.
 10	 *
 11	 * While the Solo DB row for <solo-process-id> is alive, resolve provider/cwd/started_at
 12	 * and extract that session's transcript via exact "Solo process ID: <id>" marker join
 13	 * into staging .orbit/agent-sessions/<provider>/<lane-slug>/.
 14	 *
 15	 * Exact marker join: the marker text must select exactly one runtime-scoped provider
 16	 * session candidate. Ambiguity or zero matches = loud failure with diagnostics.
 17	 */
 18	
 19	function orbitAgentSessionCaptureMain(array $argv): int
 20	{
 21	    // Robust arg parsing for mixed positional id + long options (works under test Process exec too)
 22	    $rawArgv = $argv;
 23	    $script = array_shift($rawArgv); // drop script name
 24	
 25	    $soloProcessId = null;
 26	    $options = [];
 27	
 28	    foreach ($rawArgv as $a) {
 29	        if (preg_match('/^--([a-z0-9-]+)(?:=(.*))?$/', $a, $m)) {
 30	            $key = str_replace('-', '_', $m[1]);
 31	            $val = $m[2] ?? true;
 32	            $options[$key] = $val;
 33	        } elseif ($soloProcessId === null && preg_match('/^\d+$/', $a)) {
 34	            $soloProcessId = (int) $a;
 35	        } elseif (preg_match('/^--solo-process-id=(.+)$/', $a, $m)) {
 36	            $soloProcessId = (int) $m[1];
 37	        }
 38	    }
 39	
 40	    if (array_key_exists('help', $options) || $soloProcessId === null) {
 41	        fwrite(STDOUT, <<<'EOF'
 42	    Usage:
 43	      bin/orbit-agent-session-capture <solo-process-id> [--home=...] [--cwd=...] [--solo-db=...] [--orbit-dir=...] [--incarnation-started-at=<ISO8601>]
 44	
 45	    Extracts the provider session for the given live Solo process id using exact marker match
 46	    "Solo process ID: <id>" (and close variants). Writes staged capture under
 47	    .orbit/agent-sessions/<provider>/<slug>/ containing manifest.json, usage.json,
 48	    messages.jsonl, and raw/ copies.
 49	
 50	    Exits non-zero with diagnostics on missing or ambiguous marker match.
 51	    EOF);
 52	        return $soloProcessId === null ? 2 : 0;
 53	    }
 54	
 55	    if ($soloProcessId <= 0) {
 56	        fwrite(STDERR, "solo-process-id is required and must be positive\n");
 57	        return 2;
 58	    }
 59	
 60	    $home = (string) ($options['home'] ?? getenv('HOME'));
 61	    $cwd = realpath((string) ($options['cwd'] ?? getcwd())) ?: (string) ($options['cwd'] ?? getcwd());
 62	    $soloDb = (string) ($options['solo_db'] ?? $options['solo-db'] ?? "{$home}/.config/soloterm/solo.db");
 63	    $orbitDir = (string) ($options['orbit_dir'] ?? $options['orbit-dir'] ?? ($cwd.'/.orbit'));
 64	    $explicitProvider = $options['provider'] ?? null;
 65	    $explicitSlug = $options['slug'] ?? null;
 66	    $incarnationFloor = null;
 67	    $incarnationFloorTimestamp = null;
 68	
 69	    if (array_key_exists('provider', $options)) {
 70	        if (! is_string($explicitProvider) || ! in_array($explicitProvider, ['codex', 'claude', 'grok', 'terminal'], true)) {
 71	            fwrite(STDERR, "invalid_explicit_provider\n");
 72	
 73	            return 2;
 74	        }
 75	    }
 76	
 77	    if (array_key_exists('slug', $options)) {
 78	        if (! is_string($explicitSlug) || $explicitSlug === '' || slugify($explicitSlug) !== $explicitSlug) {
 79	            fwrite(STDERR, "invalid_explicit_slug\n");
 80	
 81	            return 2;
 82	        }
 83	    }
 84	
 85	    if (array_key_exists('incarnation_started_at', $options)) {
 86	        $incarnationFloor = $options['incarnation_started_at'];
 87	
 88	        if (! is_string($incarnationFloor) || ($incarnationFloorTimestamp = parseIso8601Timestamp($incarnationFloor)) === null) {
 89	            fwrite(STDERR, "incarnation-started-at must be a valid ISO-8601 timestamp\n");
 90	            return 2;
 91	        }
 92	    }
 93	
 94	    if (! is_file($soloDb)) {
 95	        fwrite(STDERR, "solo db not found: {$soloDb}\n");
 96	        return 2;
 97	    }
 98	
 99	    $processRow = loadSoloProcessRow($soloDb, $soloProcessId);
100	
101	    if ($processRow === null) {
102	        // Try spawned_processes as fallback for runtime liveness
103	        $processRow = loadSoloSpawnedProcess($soloDb, $soloProcessId);
104	    }
105	
106	    if ($processRow === null) {
107	        fwrite(STDERR, "solo process {$soloProcessId} not found in solo db (row not alive)\n");
108	        return 2;
109	    }
110	
111	    $kind = strtolower((string) ($processRow['kind'] ?? $processRow['process_kind'] ?? 'command'));
112	    $command = (string) ($processRow['command'] ?? '');
113	    $workingDir = realpath((string) ($processRow['working_dir'] ?? $processRow['project_path'] ?? $cwd)) ?: $cwd;
114	    $name = (string) ($processRow['name'] ?? $processRow['process_name'] ?? 'agent');
115	
116	    $provider = $explicitProvider ?: inferProviderFromCommandOrName($command, $name, $kind);
117	
118	    if ($incarnationFloor !== null && $provider !== 'codex') {
119	        fwrite(STDERR, "incarnation_floor_unsupported_provider\n");
120	        return 2;
121	    }
122	
123	    // Resolve started_at from Solo row (prefer runtime spawned_at when the row is alive)
124	    $startedAt = $processRow['spawned_at']
125	        ?? $processRow['created_at']
126	        ?? $processRow['started_at']
127	        ?? null;
128	
129	    fwrite(STDERR, sprintf(
130	        "resolved from solo.db: solo_process_id=%d provider=%s cwd=%s started_at=%s\n",
131	        $soloProcessId,
132	        $provider,
133	        $workingDir,
