136	
137	    $slug = is_string($explicitSlug) ? $explicitSlug : slugify($name ?: 'process-'.$soloProcessId).'-'.$soloProcessId;
138	    $agentSessionsRoot = rtrim($orbitDir, '/').'/agent-sessions';
139	
