151	        return 1;
152	    }
153	
154	    $providerPath = "{$canonicalAgentSessionsRoot}/{$provider}";
155	
156	    if (is_link($providerPath)) {
157	        fwrite(STDERR, "symlinked_provider_root path={$providerPath}\n");
158	
159	        return 1;
160	    }
161	
162	    orbitAgentSessionCaptureEnsureDirectory($providerPath);
163	
164	    if (is_link($providerPath) || ($providerRoot = realpath($providerPath)) === false) {
165	        fwrite(STDERR, "symlinked_provider_root path={$providerPath}\n");
166	
167	        return 1;
168	    }
169	
170	    if (dirname($providerRoot) !== $canonicalAgentSessionsRoot || basename($providerRoot) !== $provider) {
171	        fwrite(
172	            STDERR,
173	            "provider_root_not_direct_child provider_root={$providerRoot} agent_sessions_root={$canonicalAgentSessionsRoot}\n",
174	        );
175	
176	        return 1;
177	    }
178	
179	    $stagingBase = $providerRoot.'/'.$slug;
180	    $reportedStagingBase = rtrim($orbitDir, '/').'/agent-sessions/'.$provider.'/'.$slug;
181	    $temporaryStaging = uniqueStagingSiblingPath($providerRoot, $slug, 'tmp');
182	    $backupStaging = uniqueStagingSiblingPath($providerRoot, $slug, 'backup');
183	
184	    $markerNeedle = "Solo process ID: {$soloProcessId}";
185	
186	    $extract = match ($provider) {
187	        'codex' => captureCodexExact(
188	            $home,
189	            $workingDir,
190	            $soloProcessId,
191	            $startedAt,
192	            $incarnationFloor,
193	            $incarnationFloorTimestamp,
194	        ),
195	        'claude' => captureClaudeExact($home, $workingDir, $soloProcessId),
196	        'grok' => captureGrokExact($home, $workingDir, $soloProcessId),
197	        default => [
198	            'status' => 'unsupported',
199	            'reason' => $kind === 'terminal' ? 'terminal_kind_requires_waiver' : 'provider_unsupported',
200	            'checked' => [],
201	        ],
202	    };
203	
204	    if (($extract['status'] ?? null) === 'ok') {
205	        // Write staged artifacts
206	        $manifest = [
207	            'schema_version' => 1,
208	            'provider' => $provider,
209	            'status' => 'ok',
210	            'slug' => $slug,
211	            'solo_process_id' => $soloProcessId,
212	            'kind' => $kind,
213	            'started_at' => $startedAt,
214	            'marker_match' => 'exact',
215	            'artifact' => $extract['artifact'] ?? null,
216	            'source' => $extract['source'] ?? 'lane_close_capture',
217	        ];
218	
219	        if (isset($extract['disambiguation_basis'])) {
220	            $manifest['disambiguation_basis'] = $extract['disambiguation_basis'];
221	        }
222	
223	        if (isset($extract['timestamp_corroboration'])) {
