237	    } else {
238	        // Failure or unsupported path: write explicit manifest entry (supports waiver later)
239	        $manifest = [
240	            'schema_version' => 1,
241	            'provider' => $provider,
242	            'status' => $extract['status'] ?? 'missing',
243	            'slug' => $slug,
