251	
252	        if (($extract['status'] ?? null) === 'stale') {
253	            $manifest['incarnation_floor'] = $extract['incarnation_floor'];
254	            $manifest['incarnation_floor_source'] = $extract['incarnation_floor_source'];
255	            $manifest['rollout_id'] = $extract['rollout_id'];
