340	function loadSoloProcessRow(string $dbPath, int $id): ?array
341	{
342	    try {
343	        $db = new PDO('sqlite:'.$dbPath);
344	        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
345	        $columns = tableColumns($db, 'processes');
346	        $selectedColumns = array_values(array_filter(
347	            ['id', 'name', 'command', 'working_dir', 'kind', 'project_id', 'started_at', 'created_at', 'spawned_at'],
348	            fn (string $column): bool => in_array($column, $columns, true),
349	        ));
350	
351	        if (! in_array('id', $selectedColumns, true)) {
352	            return null;
353	        }
354	
355	        $select = implode(', ', array_map(quoteIdentifier(...), $selectedColumns));
356	        $stmt = $db->prepare("SELECT {$select} FROM processes WHERE id = ?");
357	        $stmt->execute([$id]);
358	        $row = $stmt->fetch(PDO::FETCH_ASSOC);
359	        return $row ?: null;
360	    } catch (Throwable $e) {
361	        return null;
362	    }
363	}
