365	function loadSoloSpawnedProcess(string $dbPath, int $id): ?array
366	{
367	    try {
368	        $db = new PDO('sqlite:'.$dbPath);
369	        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
370	        $columns = tableColumns($db, 'spawned_processes');
371	
372	        if ($columns === []) {
373	            return null;
374	        }
375	
376	        $select = [];
377	
378	        foreach ([
379	            'pid' => 'id',
380	            'id' => 'id',
381	            'process_name' => 'name',
382	            'name' => 'name',
383	            'command' => 'command',
384	            'project_path' => 'working_dir',
385	            'working_dir' => 'working_dir',
386	            'kind' => 'kind',
387	            'spawned_at' => 'spawned_at',
388	            'started_at' => 'started_at',
389	            'created_at' => 'created_at',
390	        ] as $column => $alias) {
391	            if (in_array($column, $columns, true)) {
392	                $select[] = quoteIdentifier($column).' AS '.quoteIdentifier($alias);
393	            }
394	        }
395	
396	        if (! in_array('kind', $columns, true)) {
397	            $select[] = "'agent' AS ".quoteIdentifier('kind');
398	        }
399	
400	        if ($select === []) {
401	            return null;
402	        }
403	
404	        $where = [];
405	        $params = [];
406	
407	        if (in_array('pid', $columns, true)) {
408	            $where[] = quoteIdentifier('pid').' = ?';
409	            $params[] = $id;
410	        }
411	
412	        if (in_array('id', $columns, true)) {
413	            $where[] = quoteIdentifier('id').' = ?';
414	            $params[] = $id;
415	        }
416	
417	        if (in_array('process_name', $columns, true)) {
418	            $where[] = quoteIdentifier('process_name').' LIKE ?';
419	            $params[] = '%'.$id.'%';
420	        }
421	
422	        if ($where === []) {
423	            return null;
424	        }
425	
426	        $stmt = $db->prepare('SELECT '.implode(', ', $select).' FROM spawned_processes WHERE '.implode(' OR ', $where).' LIMIT 1');
427	        $stmt->execute($params);
428	        $row = $stmt->fetch(PDO::FETCH_ASSOC);
429	        return $row ?: null;
430	    } catch (Throwable $e) {
431	        return null;
432	    }
433	}
