436	 * @return list<string>
437	 */
438	function tableColumns(PDO $db, string $table): array
439	{
440	    $columns = [];
441	    $stmt = $db->query('PRAGMA table_info('.quoteIdentifier($table).')');
442	
443	    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
444	        if (isset($row['name']) && is_string($row['name'])) {
445	            $columns[] = $row['name'];
446	        }
447	    }
448	
449	    return $columns;
450	}
