457	function inferProviderFromCommandOrName(string $command, string $name, string $kind): string
458	{
459	    $hay = strtolower($command.' '.$name);
460	    if (str_contains($hay, 'codex') || str_contains($hay, 'openai') || str_contains($hay, 'o1')) {
461	        return 'codex';
462	    }
463	    if (str_contains($hay, 'claude') || str_contains($hay, 'anthropic')) {
464	        return 'claude';
465	    }
466	    if (str_contains($hay, 'grok') || str_contains($hay, 'xai')) {
467	        return 'grok';
468	    }
469	    if ($kind === 'terminal') {
470	        return 'terminal';
471	    }
472	    // default to codex for agent workers in this harness
473	    return 'codex';
474	}
