476	function slugify(string $value): string
477	{
478	    $slug = strtolower((string) preg_replace('/[^a-zA-Z0-9]+/', '-', $value));
479	    $slug = trim($slug, '-');
480	    return $slug === '' ? 'session' : $slug;
481	}
