483	function uniqueStagingSiblingPath(string $providerRoot, string $slug, string $kind): string
484	{
485	    do {
486	        $path = rtrim($providerRoot, '/')."/.{$slug}.{$kind}-".bin2hex(random_bytes(8));
487	    } while (file_exists($path) || is_link($path));
488	
489	    return $path;
490	}
