492	function fileContains(string $path, string $needle): bool
493	{
494	    if (!is_file($path)) {
495	        return false;
496	    }
497	    $fh = fopen($path, 'r');
498	    if ($fh === false) {
499	        return false;
500	    }
501	    while (!feof($fh)) {
502	        $chunk = fread($fh, 8192);
503	        if ($chunk !== false && str_contains($chunk, $needle)) {
504	            fclose($fh);
505	            return true;
506	        }
507	    }
508	    fclose($fh);
509	    return false;
510	}
