512	/** @return list<string> */
513	function findFiles(string $root, string $glob): array
514	{
515	    $files = [];
516	    if (!is_dir($root)) {
517	        return $files;
518	    }
519	    $it = new RecursiveIteratorIterator(
520	        new RecursiveDirectoryIterator($root, RecursiveDirectoryIterator::SKIP_DOTS),
521	        RecursiveIteratorIterator::SELF_FIRST,
522	    );
523	    foreach ($it as $entry) {
524	        if ($entry->isFile() && fnmatch($glob, $entry->getFilename())) {
525	            $files[] = $entry->getPathname();
526	        }
527	    }
528	    return $files;
529	}
