531	function captureCodexExact(
532	    string $home,
533	    string $cwd,
534	    int $soloProcessId,
535	    mixed $startedAt,
536	    ?string $incarnationFloor,
537	    ?DateTimeImmutable $incarnationFloorTimestamp,
538	): array
539	{
540	    $root = "{$home}/.codex/sessions";
541	    $candidates = [];
542	    $checked = [];
543	    $rollouts = findFiles($root, '*.jsonl');
544	
545	    foreach ($rollouts as $file) {
546	        $checked[] = $file;
547	        if (! codexFileHasScopedMarker($file, $soloProcessId)) {
548	            continue;
549	        }
550	        $candidates[] = $file;
551	    }
552	
553	    if ($candidates === []) {
554	        return [
555	            'status' => 'missing',
556	            'reason' => 'exact_marker_not_found',
557	            'checked' => array_slice($checked, 0, 20),
558	        ];
559	    }
560	
561	    $normalizedCwd = normalizeCodexCwd($cwd);
562	    $fullOwners = [];
563	    $partialOwners = [];
564	    $matchedCandidates = [];
565	    $ownedCandidates = [];
566	
567	    foreach ($candidates as $candidate) {
568	        $context = codexCandidateContext($candidate);
569	        $ownershipClass = match (true) {
570	            $context['normalized_cwd'] !== $normalizedCwd => 'foreign_cwd',
571	            $context['primary_solo_process_id'] === $soloProcessId => 'full',
572	            $context['primary_solo_process_id'] === null => 'partial(no_primary_identity)',
573	            default => 'foreign_primary_identity',
574	        };
575	        $diagnostic = [
576	            'path' => $candidate,
577	            'ownership_class' => $ownershipClass,
578	            'normalized_cwd' => $context['normalized_cwd'],
579	            'primary_solo_process_id' => $context['primary_solo_process_id'],
580	        ];
581	        $matchedCandidates[] = $diagnostic;
582	
583	        if ($context['normalized_cwd'] !== $normalizedCwd) {
584	            continue;
585	        }
586	
587	        $owner = [
588	            ...$diagnostic,
589	            'timestamp' => $context['timestamp'],
590	        ];
591	
592	        if ($context['primary_solo_process_id'] === $soloProcessId) {
593	            $fullOwners[] = $owner;
594	            $ownedCandidates[] = $diagnostic;
595	
596	            continue;
597	        }
598	
599	        if ($context['primary_solo_process_id'] === null) {
600	            $partialOwners[] = $owner;
601	            $ownedCandidates[] = $diagnostic;
602	        }
603	    }
604	
605	    if (count($fullOwners) > 1 || ($fullOwners === [] && count($partialOwners) > 1)) {
606	        return [
607	            'status' => 'ambiguous',
608	            'reason' => 'ambiguous_duplicate_markers',
609	            'checked' => array_slice($checked, 0, 20),
610	            'matched_candidates' => array_slice($matchedCandidates, 0, 20),
611	            'owned_candidates' => array_slice($ownedCandidates, 0, 20),
612	        ];
613	    }
614	
615	    if ($fullOwners === [] && $partialOwners === []) {
616	        return [
617	            'status' => 'missing',
618	            'reason' => 'no_owned_marker_transcript',
619	            'checked' => array_slice($checked, 0, 20),
620	            'matched_candidates' => array_slice($matchedCandidates, 0, 20),
621	            'owned_candidates' => [],
622	        ];
623	    }
624	
625	    $ownership = $fullOwners !== [] ? 'full' : 'partial(no_primary_identity)';
626	    $chosenOwner = $fullOwners[0] ?? $partialOwners[0];
627	    $chosen = $chosenOwner['path'];
628	    $timestampCorroboration = codexTimestampCorroboration($chosenOwner['timestamp'], $startedAt);
629	    $disambiguationBasis = sprintf(
630	        'provider=codex; ownership=%s; normalized_cwd=exact; primary_solo_process_id=%s; timestamp_corroboration=%s',
631	        $ownership,
632	        $ownership === 'full' ? (string) $soloProcessId : 'none',
633	        $timestampCorroboration,
634	    );
635	
636	    $incarnationActivity = null;
637	
638	    if ($incarnationFloor !== null && $incarnationFloorTimestamp !== null) {
639	        $incarnationActivity = codexIncarnationActivity($chosen);
640	
641	        if (
642	            $incarnationActivity['last_activity_timestamp'] === null
643	            || $incarnationActivity['last_activity_timestamp'] < $incarnationFloorTimestamp
644	        ) {
645	            return [
646	                'status' => 'stale',
647	                'reason' => 'stale_pre_restart_session',
648	                'checked' => array_slice($checked, 0, 20),
649	                'incarnation_floor' => $incarnationFloor,
650	                'incarnation_floor_source' => 'caller_attested',
651	                'rollout_id' => $incarnationActivity['rollout_id'],
652	                'last_activity_at' => $incarnationActivity['last_activity_at'],
653	            ];
654	        }
655	    }
656	
657	    // Parse minimal usage + messages from the rollout (reuse light logic)
658	    $messages = [];
659	    $usage = ['input_tokens' => 0, 'output_tokens' => 0, 'total_tokens' => 0];
660	    foreach (jsonl($chosen) as $row) {
661	        $type = $row['type'] ?? '';
662	        if ($type === 'response_item' && isset($row['payload']['content'])) {
663	            foreach ($row['payload']['content'] as $c) {
664	                if (isset($c['text'])) {
665	                    $messages[] = ['role' => $row['payload']['role'] ?? 'unknown', 'content' => $c['text']];
666	                }
667	            }
668	        }
669	        if ($type === 'event_msg' && ($row['payload']['type'] ?? '') === 'token_count') {
670	            $u = $row['payload']['info']['total_token_usage'] ?? [];
671	            $usage['input_tokens'] = (int) ($u['input_tokens'] ?? 0);
672	            $usage['output_tokens'] = (int) ($u['output_tokens'] ?? 0);
673	            $usage['reasoning_tokens'] = (int) ($u['reasoning_output_tokens'] ?? 0);
674	            $usage['total_tokens'] = (int) ($u['total_tokens'] ?? 0);
675	        }
676	    }
677	
678	    $messagesJsonl = implode("\n", array_map(fn($m) => json_encode(['role' => $m['role'], 'content' => $m['content']], JSON_UNESCAPED_SLASHES), $messages));
679	
680	    $result = [
681	        'status' => 'ok',
682	        'source' => 'codex_exact_marker',
683	        'artifact' => $chosen,
684	        'usage' => $usage,
685	        'messages_jsonl' => $messagesJsonl,
686	        'raw_files' => [['path' => $chosen, 'archive_name' => basename($chosen)]],
687	    ];
688	
689	    $result['disambiguation_basis'] = $disambiguationBasis;
690	    $result['timestamp_corroboration'] = $timestampCorroboration;
691	
692	    if ($incarnationFloor !== null && $incarnationActivity !== null) {
693	        $result['incarnation_floor'] = $incarnationFloor;
694	        $result['incarnation_floor_source'] = 'caller_attested';
695	        $result['rollout_id'] = $incarnationActivity['rollout_id'];
696	        $result['last_activity_at'] = $incarnationActivity['last_activity_at'];
697	    }
698	
699	    return $result;
700	}

