 773	                $base = $payload['base_instructions'] ?? '';
 774	                $baseText = is_array($base) && isset($base['text'])
 775	                    ? (string) $base['text']
 776	                    : (is_string($base) ? $base : '');
 777	                $baseInstructionIdentities = standaloneSoloProcessIdsFromIdentityText($baseText);
 778	
 779	                if (count($baseInstructionIdentities) > 1) {
 780	                    $baseInstructionsIdentityAmbiguous = true;
 781	                } elseif (count($baseInstructionIdentities) === 1) {
 782	                    $baseInstructionsIdentity = $baseInstructionIdentities[0];
 783	                }
 784	            }
 785	
 786	            continue;
 787	        }
 788	
 789	        if ($firstUserMessageSeen || ($row['type'] ?? null) !== 'response_item') {
