 838	function normalizeCodexCwd(?string $cwd): ?string
 839	{
 840	    if ($cwd === null || trim($cwd) === '') {
 841	        return null;
 842	    }
 843	
 844	    $resolved = realpath($cwd);
 845	
 846	    if ($resolved !== false) {
 847	        return $resolved;
 848	    }
 849	
 850	    $isAbsolute = str_starts_with($cwd, '/');
 851	    $segments = [];
 852	
 853	    foreach (preg_split('~/+~', $cwd) ?: [] as $segment) {
 854	        if ($segment === '' || $segment === '.') {
 855	            continue;
 856	        }
 857	
 858	        if ($segment === '..') {
 859	            if ($segments !== [] && end($segments) !== '..') {
 860	                array_pop($segments);
 861	            } elseif (! $isAbsolute) {
 862	                $segments[] = $segment;
 863	            }
 864	
 865	            continue;
 866	        }
 867	
 868	        $segments[] = $segment;
 869	    }
 870	
 871	    $normalized = ($isAbsolute ? '/' : '').implode('/', $segments);
 872	
 873	    if ($normalized !== '') {
 874	        return $normalized;
 875	    }
 876	
 877	    return $isAbsolute ? '/' : '.';
 878	}
