 880	function codexTimestampCorroboration(mixed $timestamp, mixed $startedAt): string
 881	{
 882	    if ($timestamp === null || $timestamp === '' || $startedAt === null || $startedAt === '') {
 883	        return 'unavailable';
 884	    }
 885	
 886	    $sessionTimestamp = parseCodexTimestamp($timestamp);
 887	    $soloStartedAt = parseCodexTimestamp($startedAt);
 888	
 889	    if ($sessionTimestamp === null || $soloStartedAt === null) {
 890	        return 'malformed';
 891	    }
 892	
 893	    $now = new DateTimeImmutable('now', new DateTimeZone('UTC'));
 894	
 895	    if ($sessionTimestamp > $now || $soloStartedAt > $now) {
 896	        return 'malformed';
 897	    }
 898	
 899	    if ($sessionTimestamp < $soloStartedAt) {
 900	        return 'resumed-predates-start';
 901	    }
 902	
 903	    return 'corroborated';
 904	}
