314	        if (str_starts_with($lines[$index], '- Session archive:')) {
315	            $lines[$index] = $bullet;
316	
317	            return implode("\n", $lines);
318	        }
319	    }
320	
321	    $insertAt = $sectionEnd;
322	
323	    while ($insertAt > $sectionStart + 1 && trim($lines[$insertAt - 1]) === '') {
324	        $insertAt--;
325	    }
326	
327	    array_splice($lines, $insertAt, 0, [$bullet]);
328	
329	    return implode("\n", $lines);
330	}
