593	/**
594	 * Keeps the child's stderr separate from its stdout so warnings on successful
595	 * runs pass through to the operator without corrupting the JSON payload.
596	 *
597	 * @param list<string> $command
598	 *
599	 * @return array{0: int, 1: string, 2: string}
600	 */
601	function runCommand(array $command): array
602	{
603	    $stderrPath = tempnam(sys_get_temp_dir(), 'orbit-session-archive-stderr-');
604	    $redirect = $stderrPath === false ? '2>&1' : '2>' . escapeshellarg($stderrPath);
605	    $output = [];
606	    $exitCode = 0;
607	    exec(implode(' ', array_map('escapeshellarg', $command)) . ' ' . $redirect, $output, $exitCode);
608	    $stderr = '';
609	
610	    if ($stderrPath !== false) {
611	        $stderr = (string) file_get_contents($stderrPath);
612	        unlink($stderrPath);
613	    }
614	
615	    return [$exitCode, implode("\n", $output), $stderr];
616	}
