681	/**
682	 * Returns true only when the active staging tree contains manifest-backed
683	 * captures. Malformed or empty staging should not suppress fallback extraction.
684	 */
685	function hasStagedCaptures(string $dir, int $agentSessionsDepth = 0): bool
686	{
687	    if (! is_dir($dir) || is_link($dir)) {
688	        return false;
689	    }
690	
691	    $iterator = new DirectoryIterator($dir);
692	
693	    foreach ($iterator as $entry) {
694	        if ($entry->isDot()) {
695	            continue;
696	        }
697	
698	        if ($entry->isLink() && $entry->isDir()) {
699	            continue;
700	        }
701	
702	        if ($entry->isDir()) {
703	            if ($agentSessionsDepth === 1 && isForeignTemporaryCaptureDirectory($entry->getPathname())) {
704	                continue;
705	            }
706	
707	            if (hasStagedCaptures($entry->getPathname(), $agentSessionsDepth + 1)) {
708	                return true;
709	            }
710	
711	            continue;
712	        }
713	
714	        if ($entry->isFile() && $entry->getFilename() === 'manifest.json') {
715	            return true;
716	        }
717	    }
718	
719	    return false;
720	}
