 87	 * @return array<string, mixed>
 88	 */
 89	function build_session_index(string $sessionsDir): array
 90	{
 91	    $paths = glob("{$sessionsDir}/*", GLOB_ONLYDIR) ?: [];
 92	    $records = [];
 93	
 94	    sort($paths, SORT_STRING);
 95	
 96	    foreach ($paths as $path) {
 97	        $basename = basename($path);
 98	
 99	        if (preg_match(ARCHIVE_NAME_PATTERN, $basename, $matches) !== 1) {
100	            continue;
101	        }
102	
103	        $records[] = parse_archive($path, $matches[1], $matches[2]);
104	    }
105	
106	    return [
107	        'schema_version' => 1,
108	        'generated_from' => '.orbit/sessions/YYYY-MM-DD-HHMMSS-<slug>',
109	        'record_count' => count($records),
110	        'records' => $records,
111	    ];
112	}
