215	function parse_candidate_signals(string $loop): array
216	{
217	    $section = markdown_section($loop, 'Final Distillation');
218	    $classifications = [];
219	    $total = 0;
220	
221	    if ($section === null || ! preg_match('/^- Candidate signals:\s*\R(.*?)(?=^- [A-Z].*?:|\z)/ms', $section, $matches)) {
222	        return [
223	            'total' => 0,
