225	        ];
226	    }
227	
228	    foreach (preg_split('/\R/', trim($matches[1])) ?: [] as $line) {
229	        if (! preg_match('/^\s*-\s*(.+)$/', $line, $signal)) {
230	            continue;
231	        }
232	
233	        $value = trim($signal[1]);
234	
235	        if ($value === '' || strcasecmp($value, 'none') === 0) {
236	            continue;
237	        }
238	
239	        $total++;
240

240	
241	        if (preg_match('/\s->\s([a-z-]+)\s->\s/i', $value, $classification) !== 1) {
242	            $classifications['unknown'] = ($classifications['unknown'] ?? 0) + 1;
243	
244	            continue;
245	        }
246	
247	        $key = strtolower($classification[1]);
248	        $classifications[$key] = ($classifications[$key] ?? 0) + 1;
249	    }
250	
251	    ksort($classifications);
252	
253	    return [
254	        'total' => $total,
255	        'classifications' => $classifications,
