492	{
493	    $value = trim($value);
494	
495	    if ($value === '' || str_contains($value, '<')) {
496	        return 'unknown';
497	    }
498	
499	    $normalized = normalize_whitespace(rtrim($value, '.,;:!?'));
500	
501	    if (preg_match('/^`?(complete \+ loop improvement|complete|blocked)`?(?=$|[ \t]+-[ \t]+)/i', $normalized, $matches)) {
