508	function normalize_analyzer_verdict(string $value): string
509	{
510	    $value = trim($value);
511	
512	    if ($value === '' || str_contains($value, '<')) {
513	        return 'unknown';
514	    }
515	
516	    $verdictCandidate = $value;
517	
518	    if (preg_match('/^`?Verdict:\s*/i', $verdictCandidate, $matches) === 1) {
519	        $verdictCandidate = substr($verdictCandidate, strlen($matches[0]));
520	    }
521	
522	    if (preg_match(
523	        '/^`?(not used|not applicable|skipped|deferred)`?(?=$|[.,;:!?]|[ \t]+(?:-[ \t]+|because\b|for\b))/i',
524	        $verdictCandidate,
525	        $matches,
526	    )) {
527	        return strtolower($matches[1]) === 'deferred' ? 'deferred' : 'not used';
528	    }
529	
530	    if (preg_match('/^`?(yes|no)(?:`|[.,;:!?])*\s*$/i', $verdictCandidate, $matches)) {
531	        return strtolower($matches[1]);
532	    }
533	
534	    if (preg_match(
535	        '/^`?(proper|flawed|blocked-by-missing-evidence|blocked by missing evidence)`?(?=$|[.,;:!?]|[ \t]+(?:-[ \t]+|because\b|for\b))/i',
536	        $verdictCandidate,
537	        $matches,
538	    )) {
539	        $normalizedVerdict = strtolower($matches[1]);
540	
541	        if ($normalizedVerdict === 'blocked by missing evidence') {
542	            $normalizedVerdict = 'blocked-by-missing-evidence';
543	        }
544	
545	        return $normalizedVerdict;
546	    }
547	
548	    return normalize_value($value);
549	}
